SELECT FROM MARKETING_CUSTOMER_TAG_IMPORT_DETAIL
batch_id = #{batchId}
AND approval_status = #{approvalStatus}
AND (cust_name LIKE CONCAT('%', #{keyword}, '%') OR unified_credit_code = #{keyword})
ORDER BY CASE validation_status WHEN 'ERROR' THEN 1 WHEN 'REJECTED' THEN 2 ELSE 3 END, row_no ASC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM MARKETING_CUSTOMER_TAG_IMPORT_DETAIL

    batch_id = #{batchId}

      AND approval_status = #{approvalStatus}


      AND (cust_name LIKE CONCAT('%', #{keyword}, '%')
           OR unified_credit_code = #{keyword})

SELECT d.* FROM MARKETING_CUSTOMER_TAG_IMPORT_DETAIL d JOIN MARKETING_CUSTOMER_TAG_IMPORT_BATCH b ON b.id = d.batch_id WHERE b.tag_id = #{tagId} AND b.record_status = 'ACTIVE' AND d.validation_status = 'VALID' AND d.approval_status = 'PENDING'
AND (d.cust_name LIKE CONCAT('%', #{keyword}, '%') OR d.unified_credit_code = #{keyword})
ORDER BY b.import_time ASC, d.row_no ASC LIMIT #{offset}, #{limit}

SELECT d.* FROM MARKETING_CUSTOMER_TAG_IMPORT_DETAIL d WHERE d.reviewed_by = #{reviewedBy}
AND (d.cust_name LIKE CONCAT('%', #{keyword}, '%') OR d.unified_credit_code = #{keyword})
ORDER BY d.reviewed_time DESC, d.id DESC LIMIT #{offset}, #{limit}

